<script>
  KosShell.ready.then(({ user, summary }) => {
    const by = summary.rooms_by_status, total = summary.total_rooms;
    const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    const pct = total ? Math.round(by.terisi / total * 100) : 0;
    set('dashName', user.name); set('dashTotal', total);
    set('dashMonth', 'Bulan Ini (' + new Date().toLocaleDateString('id-ID', { month: 'long', year: 'numeric' }) + ')');
    set('dOcc', by.terisi); set('dOccTotal', total); set('dPct', pct);
    const bar = document.getElementById('dBar'); if (bar) bar.style.width = pct + '%';
    set('dFree', by.kosong + by.butuh_perbaikan); set('dAvail', by.kosong); set('dRepair', by.butuh_perbaikan);
    set('dActive', by.terisi);
  }).catch(() => {});
</script>
